package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type Vector struct {
	data     []int
	size     int
	capacity int
}

func (v *Vector) Slice(start int, end int) any {
	end = ((end % v.size) + v.size) % v.size
	return Join(v.data[start:end], ", ")
}

func (v *Vector) Contains(value int) bool {
	var recursiva func(index int) bool

	recursiva = func(index int) bool {

		if index == v.size {
			return false
		}

		if v.data[index] == value {
			return true
		}

		index++
		return recursiva(index)
	}

	return recursiva(0)
}

func (v *Vector) IndexOf(value int) any {
	var recursiva func(index int) int

	recursiva = func(index int) int {

		if index == v.size {
			return -1
		}

		if v.data[index] == value {
			return index
		}

		index++
		return recursiva(index)
	}

	return recursiva(0)
}

func (v *Vector) Erase(index int) any {
	if index < 0 || index > v.size-1 {
		return "index out of range"
	}
	v.data = append(v.data[:index], v.data[index+1:]...)
	v.size--
	return nil
}

func (v *Vector) Insert(index int, value int) any {
	if index < 0 || index > v.size-1 {
		return "index out of range"
	}
	if v.size >= v.capacity {
		v.capacity *= 2
	}
	v.data = append(v.data[:index], append([]int{value}, v.data[index:]...)...)
	v.size++
	return nil
}

func (v *Vector) PopBack() any {
	if v.size == 0 {
		return "vector is empty"
	}
	v.data = v.data[:v.size-1]
	v.size--
	return nil
}

func (v *Vector) Reserve(newCapacity int) {
	v.capacity = newCapacity
}

func (v *Vector) Clear() {
	v.data = nil
	v.size = 0
}

func (v *Vector) Set(index int, value int) any {
	if index > v.size-1 || index < 0 {
		return "index out of range"
	}
	v.data[index] = value
	return nil
}

func (v *Vector) At(index int) (int, any) {
	if index > v.size-1 || index < 0 {
		return 0, "index out of range"
	}
	return v.data[index], nil
}

func (v *Vector) PushBack(value int) {
	if v.size >= v.capacity {
		v.capacity *= 2
	}
	v.data = append(v.data, value)
	v.size++
}

func (v *Vector) Status() string {
	return fmt.Sprintf("size:%d capacity:%d", v.size, v.capacity)
}

func NewVector(capacity int) *Vector {
	return &Vector{
		data:     make([]int, 0, capacity), // nunca use len(data) ou cap(data) ou qq método do go de manipulação de array
		size:     0,
		capacity: capacity,
	}
}

func Join(slice []int, sep string) string {
	if len(slice) == 0 {
		return "[]"
	}
	var result strings.Builder
	fmt.Fprintf(&result, "%d", slice[0])
	for _, value := range slice[1:] {
		fmt.Fprintf(&result, "%s%d", sep, value)
	}
	return "[" + result.String() + "]"
}

func main() {
	var line, cmd string
	scanner := bufio.NewScanner(os.Stdin)

	v := NewVector(0)
	for {
		fmt.Print("$")
		if !scanner.Scan() {
			break
		}
		line = scanner.Text()
		fmt.Println(line)
		parts := strings.Fields(line)
		if len(parts) == 0 {
			continue
		}
		cmd = parts[0]

		switch cmd {
		case "end":
			return
		case "init":
			value, _ := strconv.Atoi(parts[1])
			v = NewVector(value)
		case "push":
			for _, part := range parts[1:] {
				value, _ := strconv.Atoi(part)
				v.PushBack(value)
			}
		case "show":
			fmt.Println(Join(v.data, ", "))
		case "status":
			fmt.Println(v.Status())
		case "pop":
			err := v.PopBack()
			if err != nil {
				fmt.Println(err)
			}
		case "insert":
			index, _ := strconv.Atoi(parts[1])
			value, _ := strconv.Atoi(parts[2])
			err := v.Insert(index, value)
			if err != nil {
				fmt.Println(err)
			}
		case "erase":
			index, _ := strconv.Atoi(parts[1])
			err := v.Erase(index)
			if err != nil {
				fmt.Println(err)
			}
		case "indexOf":
			value, _ := strconv.Atoi(parts[1])
			index := v.IndexOf(value)
			fmt.Println(index)
		case "contains":
			value, _ := strconv.Atoi(parts[1])
			if v.Contains(value) {
				fmt.Println("true")
			} else {
				fmt.Println("false")
			}
		case "clear":
			v.Clear()
		case "capacity":
			// fmt.Println(v.Capacity())
		case "get":
			index, _ := strconv.Atoi(parts[1])
			value, err := v.At(index)
			if err != nil {
				fmt.Println(err)
			} else {
				fmt.Println(value)
			}
		case "set":
			index, _ := strconv.Atoi(parts[1])
			value, _ := strconv.Atoi(parts[2])
			err := v.Set(index, value)
			if err != nil {
				fmt.Println(err)
			}

		case "reserve":
			newCapacity, _ := strconv.Atoi(parts[1])
			v.Reserve(newCapacity)
		case "slice":
			start, _ := strconv.Atoi(parts[1])
			end, _ := strconv.Atoi(parts[2])
			slice := v.Slice(start, end)
			fmt.Println(slice)
		default:
			fmt.Println("fail: comando invalido")
		}
	}
}
